//! RED slice for v0.9.0 view transitions: `SurfaceFx::Offset` and `SurfaceFx::Blend`.
//!
//! Both variants are no-op stubs today, so every test that needs real movement or colour
//! change FAILS by design; tests marked "guard" pass today and must keep passing.
//! Design: `docs/design/v0.9-view-transitions.md`.
//!
//! OWNER RULE: every transition is exercised with a synthetic truecolor sprite region
//! composited on the surface (`paint_sprite`). The fixture is generated by a formula in this
//! file; no image or avatar asset is read. The sprite must survive a slide intact and a
//! blend must apply the exact per-cell lerp to the sprite's own colours.
use gibson::capability::quantize_color;
use gibson::*;

const W: u16 = 30;
const H: u16 = 14;
const SPRITE_W: u16 = 12;
const SPRITE_H: u16 = 6;
const SPRITE_X: u16 = 4;
const SPRITE_Y: u16 = 3;
const HALF_BLOCK: &str = "\u{2580}";

// ---------------------------------------------------------------- sprite fixture

fn sprite_fg(x: u16, y: u16) -> Color {
    Color::Rgb(
        (16 + 17 * x) as u8,
        (16 + 30 * y) as u8,
        ((x * 7 + y * 11) % 200 + 20) as u8,
    )
}

fn sprite_bg(x: u16, y: u16) -> Color {
    match sprite_fg(x, y) {
        Color::Rgb(r, g, b) => Color::Rgb(255 - r, 255 - g, 255 - b),
        _ => unreachable!(),
    }
}

fn sprite_cell(x: u16, y: u16) -> Cell {
    Cell::new(
        Glyph::new(HALF_BLOCK),
        Style::new().fg(sprite_fg(x, y)).bg(sprite_bg(x, y)),
    )
}

fn paint_sprite(s: &mut Surface, ox: u16, oy: u16) {
    for y in 0..SPRITE_H {
        for x in 0..SPRITE_W {
            assert!(s.set_cell(ox + x, oy + y, sprite_cell(x, y)));
        }
    }
}

/// A view with a bold label, a wide glyph row, and the sprite over a transparent background.
fn scene() -> Surface {
    let mut s = Surface::new_transparent(W, H);
    s.print_str(0, 0, "VIEW", Style::new().bold(), None);
    s.print_str(2, 12, "AB\u{754c}CD", Style::new(), None);
    paint_sprite(&mut s, SPRITE_X, SPRITE_Y);
    s
}

fn painted(s: &Surface) -> usize {
    s.cells.iter().filter(|c| !c.transparent).count()
}

fn lead(s: &Surface, x: u16, y: u16) -> String {
    s.get(x, y).unwrap().glyph.grapheme.to_string()
}

/// No orphan continuation and no wide lead without its continuation.
fn valid(s: &Surface) {
    for y in 0..s.height {
        for x in 0..s.width {
            let c = s.get(x, y).unwrap();
            if c.is_continuation {
                assert!(x > 0, "continuation at column 0");
                let prev = s.get(x - 1, y).unwrap();
                assert!(
                    !prev.transparent && !prev.is_continuation && prev.glyph.display_width == 2
                );
            } else if !c.transparent && !c.style_only && c.glyph.display_width == 2 {
                assert!(x + 1 < s.width, "wide lead on the last column");
                let next = s.get(x + 1, y).unwrap();
                assert!(next.is_continuation && !next.transparent);
            }
        }
    }
}

fn run(effect: SurfaceFx, s: &Surface) -> Surface {
    let mut out = s.clone();
    effect.apply(&mut out);
    out
}

// ---------------------------------------------------------------- independent oracles

/// Naive reference for `Offset`: shift, clip, vacate, drop straddling wide glyphs whole.
fn reference_offset(src: &Surface, dx: i32, dy: i32) -> Surface {
    let mut out = Surface::new_transparent(src.width, src.height);
    for y in 0..src.height {
        for x in 0..src.width {
            let c = src.get(x, y).unwrap();
            if c.transparent || c.is_continuation {
                continue;
            }
            let span: i32 = if c.style_only {
                1
            } else {
                i32::from(c.glyph.display_width.max(1))
            };
            let (tx, ty) = (i32::from(x) + dx, i32::from(y) + dy);
            if tx < 0 || ty < 0 || ty >= i32::from(src.height) || tx + span > i32::from(src.width) {
                continue;
            }
            let i = ty as usize * src.width as usize + tx as usize;
            out.cells[i] = c.clone();
            if span == 2 {
                out.cells[i + 1] = src.get(x + 1, y).unwrap().clone();
            }
        }
    }
    out
}

fn unit(t: f32) -> f32 {
    if t.is_nan() {
        0.0
    } else {
        t.clamp(0.0, 1.0)
    }
}

/// The documented rule for one colour channel. Both endpoints resolvable: exact lerp.
/// Otherwise (current is `Reset`/`None`, or `toward` is `Reset`): step at t >= 0.5.
fn blend_channel(c: Option<Color>, toward: Color, t: f32) -> Option<Color> {
    let t = unit(t);
    match c {
        Some(c) if c != Color::Reset && toward != Color::Reset => c.lerp_resolved(toward, t),
        _ => {
            if t >= 0.5 {
                Some(toward)
            } else {
                c
            }
        }
    }
}

fn reference_blend(src: &Surface, toward: Color, t: f32) -> Surface {
    let mut out = src.clone();
    for c in &mut out.cells {
        if !c.transparent {
            c.style.fg = blend_channel(c.style.fg, toward, t);
            c.style.bg = blend_channel(c.style.bg, toward, t);
        }
    }
    out
}

// ---------------------------------------------------------------- Offset

#[test]
fn offset_zero_is_identity_with_sprite_guard() {
    let s = scene();
    assert_eq!(run(SurfaceFx::Offset { dx: 0, dy: 0 }, &s), s);
}

#[test]
fn offset_matches_reference_over_a_grid_with_sprite_present() {
    let s = scene();
    for dx in [-30, -14, -5, -1, 0, 1, 3, 12, 25, 29, 30] {
        for dy in [-14, -7, -1, 0, 1, 5, 13, 14] {
            let got = run(SurfaceFx::Offset { dx, dy }, &s);
            valid(&got);
            assert_eq!(got, reference_offset(&s, dx, dy), "dx {dx} dy {dy}");
        }
    }
}

#[test]
fn offset_moves_content_and_the_sprite_arrives_intact() {
    let s = scene();
    let got = run(SurfaceFx::Offset { dx: 5, dy: 1 }, &s);
    // Text moved.
    assert_eq!(lead(&got, 5, 1), "V");
    assert_eq!(lead(&got, 8, 1), "W");
    // Every sprite cell: glyph, fg and bg preserved at the shifted position.
    for y in 0..SPRITE_H {
        for x in 0..SPRITE_W {
            let at = got.get(SPRITE_X + 5 + x, SPRITE_Y + 1 + y).unwrap();
            assert_eq!(at, &sprite_cell(x, y), "sprite cell ({x},{y})");
        }
    }
    // Nothing was lost, nothing invented.
    assert_eq!(painted(&got), painted(&s));
    // Vacated cells: the first five columns and the first row are transparent.
    for y in 0..H {
        for x in 0..H.min(5) {
            assert!(got.get(x, y).unwrap().transparent, "vacated ({x},{y})");
        }
    }
    assert!(got.get(0, 0).unwrap().transparent);
}

#[test]
fn offset_clips_at_the_edges_and_the_sprite_is_clipped_not_distorted() {
    let s = scene();
    // Sprite columns 0..6 stay (x = 24..29); rows 1..6 stay (y = -1 + sy >= 0).
    let got = run(SurfaceFx::Offset { dx: 20, dy: -4 }, &s);
    valid(&got);
    let mut sprite_cells = 0;
    for sy in 1..SPRITE_H {
        for sx in 0..6 {
            let at = got.get(SPRITE_X + 20 + sx, SPRITE_Y + sy - 4).unwrap();
            assert_eq!(at, &sprite_cell(sx, sy), "kept sprite cell ({sx},{sy})");
            sprite_cells += 1;
        }
    }
    let half_blocks = got
        .cells
        .iter()
        .filter(|c| !c.transparent && c.glyph.grapheme.as_str() == HALF_BLOCK)
        .count();
    assert_eq!(
        half_blocks, sprite_cells,
        "no sprite cell leaked or duplicated"
    );
    // The label moved off the top edge entirely: vacated and clipped.
    assert!(got.get(20, 0).unwrap().transparent);
}

#[test]
fn offset_drops_a_wide_glyph_straddling_the_right_edge_whole_with_sprite_present() {
    let s = scene();
    // "AB" at 2,3; wide glyph at 4,5 -> lead 29, continuation 30 (outside): dropped whole.
    let got = run(SurfaceFx::Offset { dx: 25, dy: 0 }, &s);
    valid(&got);
    assert_eq!(lead(&got, 27, 12), "A");
    assert_eq!(lead(&got, 28, 12), "B");
    assert!(
        got.get(29, 12).unwrap().transparent,
        "half a wide glyph survived"
    );
    // The sprite's first column lands on x = 29 intact (it is narrow, so it is kept).
    assert_eq!(got.get(29, SPRITE_Y).unwrap(), &sprite_cell(0, 0));
}

#[test]
fn offset_drops_a_wide_glyph_straddling_the_left_edge_whole_with_sprite_present() {
    let s = scene();
    // Wide lead 4 -> -1: its continuation would land on column 0 as an orphan.
    let got = run(SurfaceFx::Offset { dx: -5, dy: 0 }, &s);
    valid(&got);
    assert!(
        got.get(0, 12).unwrap().transparent,
        "orphan continuation survived"
    );
    assert_eq!(lead(&got, 1, 12), "C");
    assert_eq!(lead(&got, 2, 12), "D");
    // Sprite column 1 is now the leftmost surviving column.
    assert_eq!(got.get(0, SPRITE_Y).unwrap(), &sprite_cell(1, 0));
}

// ---------------------------------------------------------------- Blend

/// Opaque coloured text plus the sprite; every painted cell has both fg and bg set.
fn blend_scene() -> Surface {
    let mut s = Surface::new_transparent(W, H);
    s.print_str(
        0,
        0,
        "HELLO",
        Style::new()
            .fg(Color::Rgb(0, 100, 200))
            .bg(Color::Rgb(10, 20, 30))
            .bold(),
        None,
    );
    paint_sprite(&mut s, SPRITE_X, SPRITE_Y);
    s
}

const TARGET: Color = Color::Rgb(100, 200, 0);

fn blend(toward: Color, t: f32) -> SurfaceFx {
    SurfaceFx::Blend { toward, t }
}

#[test]
fn blend_t0_is_identity_with_sprite_guard() {
    let s = blend_scene();
    assert_eq!(run(blend(TARGET, 0.0), &s), s);
}

#[test]
fn blend_nan_is_identity_guard() {
    let s = blend_scene();
    assert_eq!(run(blend(TARGET, f32::NAN), &s), s);
    assert_eq!(
        run(blend(TARGET, -3.0), &s),
        s,
        "t below 0 clamps to identity"
    );
}

#[test]
fn blend_t1_is_exactly_the_target_and_t_above_1_clamps() {
    let s = blend_scene();
    for t in [1.0, 7.5] {
        let got = run(blend(TARGET, t), &s);
        for (a, b) in s.cells.iter().zip(&got.cells) {
            if a.transparent {
                assert!(b.transparent);
            } else {
                assert_eq!(b.style.fg, Some(TARGET), "t {t}");
                assert_eq!(b.style.bg, Some(TARGET), "t {t}");
            }
        }
    }
}

#[test]
fn blend_half_is_the_rgb_midpoint() {
    let s = blend_scene();
    let got = run(blend(TARGET, 0.5), &s);
    let label = got.get(0, 0).unwrap();
    assert_eq!(label.style.fg, Some(Color::Rgb(50, 150, 100)));
    assert_eq!(label.style.bg, Some(Color::Rgb(55, 110, 15)));
}

#[test]
fn blend_applies_the_exact_per_cell_lerp_to_the_sprites_own_colours() {
    let s = blend_scene();
    for t in [0.1f32, 0.25, 0.5, 0.9] {
        let got = run(blend(TARGET, t), &s);
        for y in 0..SPRITE_H {
            for x in 0..SPRITE_W {
                let at = got.get(SPRITE_X + x, SPRITE_Y + y).unwrap();
                assert_eq!(at.glyph.grapheme.as_str(), HALF_BLOCK);
                assert_eq!(at.style.fg, sprite_fg(x, y).lerp_resolved(TARGET, t));
                assert_eq!(at.style.bg, sprite_bg(x, y).lerp_resolved(TARGET, t));
            }
        }
        assert_eq!(got, reference_blend(&s, TARGET, t), "t {t}");
    }
}

#[test]
fn blend_moves_colour_but_never_glyphs_or_attributes() {
    let s = blend_scene();
    let got = run(blend(TARGET, 0.5), &s);
    let mut moved = 0;
    for (a, b) in s.cells.iter().zip(&got.cells) {
        assert_eq!(a.glyph, b.glyph);
        assert_eq!(a.transparent, b.transparent);
        assert_eq!(a.is_continuation, b.is_continuation);
        assert_eq!(a.style_only, b.style_only);
        assert_eq!(a.style.bold, b.style.bold);
        assert_eq!(a.style.dim, b.style.dim);
        assert_eq!(a.style.italic, b.style.italic);
        assert_eq!(a.style.underline, b.style.underline);
        assert_eq!(a.style.reverse, b.style.reverse);
        if a.style != b.style {
            moved += 1;
        }
    }
    assert!(moved > 0, "Blend stub moved no colour (RED)");
}

fn reset_scene() -> Surface {
    let mut s = Surface::new_transparent(W, H);
    let rgb = Color::Rgb(10, 20, 30);
    s.print_str(0, 0, "a", Style::new().fg(Color::Reset).bg(rgb), None);
    s.print_str(1, 0, "b", Style::new().fg(rgb).bg(Color::Reset), None);
    s.print_str(
        2,
        0,
        "c",
        Style::new().fg(Color::Reset).bg(Color::Reset),
        None,
    );
    paint_sprite(&mut s, SPRITE_X, SPRITE_Y);
    s
}

fn assert_no_fake_gray(s: &Surface, what: &str) {
    let gray = Some(Color::Rgb(204, 204, 204));
    for c in &s.cells {
        assert_ne!(c.style.fg, gray, "{what}: fake gray fg");
        assert_ne!(c.style.bg, gray, "{what}: fake gray bg");
    }
}

#[test]
fn blend_reset_endpoints_step_at_one_half_and_never_invent_gray() {
    let s = reset_scene();
    for toward in [Color::Rgb(0, 0, 0), TARGET, Color::Reset] {
        for t in [0.0f32, 0.1, 0.25, 0.49, 0.5, 0.51, 0.75, 1.0] {
            let got = run(blend(toward, t), &s);
            assert_no_fake_gray(&got, &format!("toward {toward:?} t {t}"));
            assert_eq!(
                got,
                reference_blend(&s, toward, t),
                "toward {toward:?} t {t}"
            );
            let a = got.get(0, 0).unwrap();
            if t < 0.5 {
                assert_eq!(a.style.fg, Some(Color::Reset), "kept below one half");
            } else {
                assert_eq!(a.style.fg, Some(toward), "taken at one half and above");
            }
            // The resolvable channel of a mixed cell still lerps when `toward` is resolved.
            if toward != Color::Reset {
                assert_eq!(a.style.bg, Color::Rgb(10, 20, 30).lerp_resolved(toward, t));
            }
        }
    }
    // Sprite cells (all resolvable) follow the exact lerp even next to Reset cells.
    let got = run(blend(TARGET, 0.25), &s);
    assert_eq!(
        got.get(SPRITE_X + 3, SPRITE_Y + 2).unwrap().style.fg,
        sprite_fg(3, 2).lerp_resolved(TARGET, 0.25)
    );
}

fn dist2(a: (u8, u8, u8), b: (u8, u8, u8)) -> i32 {
    let d = |x: u8, y: u8| (i32::from(x) - i32::from(y)).pow(2);
    d(a.0, b.0) + d(a.1, b.1) + d(a.2, b.2)
}

/// `quantize_color` is the public colour-depth path (`capability::quantize_color`). It is not
/// verified here that the ANSI compiler uses this exact function on the wire; the renderer
/// route is covered by the slide test below at truecolor only.
#[test]
fn blend_sweep_downsampled_to_256_is_monotone_along_the_grey_axis() {
    let white = Color::Rgb(255, 255, 255);
    let mut s = Surface::new_transparent(4, 1);
    s.print_str(
        0,
        0,
        "x",
        Style::new()
            .fg(Color::Rgb(0, 0, 0))
            .bg(Color::Rgb(40, 40, 40)),
        None,
    );
    let mut fg = Vec::new();
    let mut bg = Vec::new();
    for i in 0..8 {
        let t = i as f32 / 7.0;
        let got = run(blend(white, t), &s);
        let c = got.get(0, 0).unwrap();
        let q = |c: Option<Color>| {
            quantize_color(c.unwrap(), ColorDepth::Ansi256)
                .unwrap()
                .to_rgb()
        };
        fg.push(dist2(q(c.style.fg), (255, 255, 255)));
        bg.push(dist2(q(c.style.bg), (255, 255, 255)));
    }
    for seq in [&fg, &bg] {
        assert!(seq.windows(2).all(|w| w[1] <= w[0]), "flicker: {seq:?}");
        assert!(
            seq[0] > seq[7],
            "sweep did not approach the target: {seq:?}"
        );
        assert_eq!(seq[7], 0, "t = 1 must land on the target palette entry");
    }
}

#[test]
fn blend_sweep_with_sprite_converges_exactly_at_256_colours() {
    // Per-cell monotonicity AFTER quantization is only guaranteed on the grey axis (above);
    // for arbitrary hues the palette is not uniform. Here: the unquantized path is monotone
    // (linearity) and t = 1 quantizes to distance 0 for every sprite cell.
    let white = Color::Rgb(255, 255, 255);
    let s = blend_scene();
    let mut prev = vec![i32::MAX; usize::from(SPRITE_W * SPRITE_H)];
    for i in 0..8 {
        let got = run(blend(white, i as f32 / 7.0), &s);
        for y in 0..SPRITE_H {
            for x in 0..SPRITE_W {
                let fg = got
                    .get(SPRITE_X + x, SPRITE_Y + y)
                    .unwrap()
                    .style
                    .fg
                    .unwrap();
                let d = dist2(fg.to_rgb(), (255, 255, 255));
                let k = usize::from(y * SPRITE_W + x);
                assert!(
                    d <= prev[k],
                    "unquantized path moved away at step {i} cell ({x},{y})"
                );
                prev[k] = d;
                if i == 7 {
                    let q = quantize_color(fg, ColorDepth::Ansi256).unwrap();
                    assert_eq!(dist2(q.to_rgb(), (255, 255, 255)), 0);
                }
            }
        }
    }
    assert!(
        prev.iter().all(|&d| d == 0),
        "t = 1 did not reach the target"
    );
}

// ---------------------------------------------------------------- renderer: no flash

const CW: u16 = 40;
const CH: u16 = 14;
const VX: u16 = 6;
const VY: u16 = 4;

/// A full-screen view: a uniform dot backdrop (so a slide changes little besides the sprite
/// and the vacated edge) with the sprite on top.
fn slide_view() -> Surface {
    let mut s = Surface::new_transparent(CW, CH);
    for y in 0..CH {
        s.print_str(0, y, &".".repeat(usize::from(CW)), Style::new(), None);
    }
    paint_sprite(&mut s, VX, VY);
    s
}

/// Wiring: `Node::raster(view).post_process([SurfaceFx::Offset { .. }])` is the public path
/// (the painter applies `node.surface_fx` to the node's local surface, src/painter.rs). The
/// ui `.motion` / MotionPlan path only emits fixed grammars and cannot carry Offset yet.
/// Frame 0 is exempt from the no-clear check: a fullscreen first frame may clear to anchor.
#[test]
fn offset_slide_with_sprite_never_clears_and_repaints_less_than_a_full_frame() {
    let mut ctx = Context::headless(RenderMode::Fullscreen, CW, CH);
    ctx.set_color_depth(ColorDepth::TrueColor);
    let mut full_repaint = 0usize;
    for i in 0..8u16 {
        let node = Node::raster(slide_view()).post_process([SurfaceFx::Offset {
            dx: i32::from(i),
            dy: 0,
        }]);
        ctx.set_root(node);
        ctx.render_now().unwrap();
        let bytes = ctx.take_output();
        if i == 0 {
            full_repaint = bytes.len();
            assert!(full_repaint > 0);
            continue;
        }
        assert!(!bytes.contains("\x1b[2J"), "frame {i} cleared the screen");
        assert!(
            !bytes.is_empty(),
            "frame {i} wrote nothing: the slide did not move"
        );
        assert!(
            bytes.len() < full_repaint,
            "frame {i} wrote {} bytes, a full repaint is {full_repaint}",
            bytes.len()
        );
        // The presented frame has the sprite at its shifted position, intact.
        for y in 0..SPRITE_H {
            for x in 0..SPRITE_W {
                let fc = ctx.frame_cell(VX + i + x, VY + y).unwrap();
                assert_eq!(fc.glyph, HALF_BLOCK, "frame {i} cell ({x},{y})");
                assert_eq!(fc.style.fg, Some(sprite_fg(x, y)), "frame {i} fg ({x},{y})");
                assert_eq!(fc.style.bg, Some(sprite_bg(x, y)), "frame {i} bg ({x},{y})");
            }
        }
        // The vacated left edge is blank and the cell just left of the sprite is backdrop.
        let row: Vec<char> = ctx.last_frame_lines()[usize::from(VY)].chars().collect();
        assert!(
            row.iter().take(usize::from(i)).all(|&c| c == ' '),
            "frame {i}: {row:?}"
        );
        assert_eq!(
            row[usize::from(VX + i - 1)],
            '.',
            "frame {i} left of sprite"
        );
    }
}
